using System.Diagnostics;
using WheelConvert.Core.Contracts;
using WheelConvert.Core.Formats;
using WheelConvert.Core.Output;
using Xunit;
using Xunit.Abstractions;

namespace WheelConvert.Converters.Media.Tests;

/// <summary>
/// Acceptance tests 3, 4, 5 and the video round-trip against the FFmpeg installed on this machine. Every test is
/// SKIPPED (with the reason in the output) when FFmpeg isn't installed, as on CI. All media is generated by FFmpeg in
/// the test's own temp folder. One class, so xUnit runs these one at a time (the cancel test counts FFmpeg processes).
/// </summary>
public sealed class RealFfmpegTests(ITestOutputHelper log) : IDisposable
{
    private readonly TestFolder _folder = new();

    public void Dispose() => _folder.Dispose();

    private static MediaConverter Converter()
    {
        var converter = new MediaConverter(() => null);
        Assert.True(converter.CheckHealth().IsAvailable);
        return converter;
    }

    private async Task<string> ToneWavAsync(int seconds = 1)
    {
        var path = _folder.File("tone.wav");
        await RealFfmpeg.GenerateAsync("-f", "lavfi", "-i", $"sine=frequency=440:duration={seconds}", "-c:a", "pcm_s16le", path);
        return path;
    }

    // ---- Acceptance test 3 ----

    [FfmpegFact]
    public async Task Sine_wav_converts_to_every_audio_target()
    {
        var source = await ToneWavAsync();
        var hash = TestFolder.Hash(source);
        var converter = Converter();

        foreach (var target in new[] { TargetCatalog.AudioMp3, TargetCatalog.AudioM4a, TargetCatalog.AudioFlac, TargetCatalog.AudioWav, TargetCatalog.AudioOgg, TargetCatalog.AudioOpus })
        {
            var result = await converter.ConvertAsync(ConversionRequest.Create(source, target), new SafeOutputWriter(), null, CancellationToken.None);
            await AssertConvertedOrEncoderMissingAsync(target, result);
        }

        Assert.Equal(hash, TestFolder.Hash(source));
        Assert.Empty(_folder.TempFiles());
    }

    // ---- Video round-trip (testsrc + sine) ----

    [FfmpegFact]
    public async Task Test_video_converts_to_every_video_target()
    {
        // 1280 wide so the GIF filter's scale='min(720,iw)' must shrink it: a 720-wide GIF proves FFmpeg received the
        // filter string exactly as built (quotes and commas intact) through ArgumentList.
        var source = _folder.File("clip.mkv");
        await RealFfmpeg.GenerateAsync(
            "-f", "lavfi", "-i", "testsrc=duration=1:size=1280x720:rate=12",
            "-f", "lavfi", "-i", "sine=frequency=440:duration=1",
            "-c:v", "mpeg4", "-c:a", "pcm_s16le", "-shortest", source);
        var hash = TestFolder.Hash(source);
        var converter = Converter();

        foreach (var target in new[] { TargetCatalog.VideoMp4, TargetCatalog.VideoWebm, TargetCatalog.VideoGif, TargetCatalog.VideoExtractMp3 })
        {
            var result = await converter.ConvertAsync(ConversionRequest.Create(source, target), new SafeOutputWriter(), null, CancellationToken.None);
            if (!await AssertConvertedOrEncoderMissingAsync(target, result))
            {
                continue;
            }

            var output = result.OutputPaths.Single();
            if (target == TargetCatalog.VideoGif)
            {
                Assert.Equal(720, GifWidth(output));
            }

            if (target == TargetCatalog.VideoExtractMp3)
            {
                Assert.Equal(_folder.File("clip (audio).mp3"), output);
            }
        }

        Assert.Equal(hash, TestFolder.Hash(source));
        Assert.Empty(_folder.TempFiles());
    }

    // ---- Acceptance test 4 ----

    [FfmpegFact]
    public async Task Corrupt_input_fails_cleanly()
    {
        var source = _folder.CreateFile("bad.wav", "this is not audio, just text pretending to be a WAV file\n"u8.ToArray());
        var hash = TestFolder.Hash(source);

        var result = await Converter().ConvertAsync(ConversionRequest.Create(source, TargetCatalog.AudioFlac), new SafeOutputWriter(), null, CancellationToken.None);

        log.WriteLine($"Corrupt input → {result.Error}: {result.Message}");
        Assert.False(result.Success);
        Assert.Contains(result.Error, new[] { ConversionError.CorruptInput, ConversionError.ToolFailed });
        Assert.Equal(hash, TestFolder.Hash(source));
        Assert.Empty(_folder.TempFiles());
        Assert.Single(Directory.GetFiles(_folder.Path));
    }

    // ---- Acceptance test 5 (real process) ----

    [FfmpegFact]
    public async Task Cancel_mid_conversion_kills_ffmpeg_and_discards_temp()
    {
        // 10 minutes of audio: long enough that AAC encoding reports progress before it finishes.
        var source = await ToneWavAsync(seconds: 600);
        var before = FfmpegPids();
        using var cts = new CancellationTokenSource();
        var progress = new CancelMidway(cts);

        var sw = Stopwatch.StartNew();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => Converter().ConvertAsync(ConversionRequest.Create(source, TargetCatalog.AudioM4a), new SafeOutputWriter(), progress, cts.Token));
        log.WriteLine($"Cancelled after {sw.ElapsedMilliseconds} ms");

        Assert.True(cts.IsCancellationRequested, "Cancelled by progress, not by something else");
        Assert.Empty(FfmpegPids().Except(before));
        Assert.Empty(_folder.TempFiles());
        Assert.Single(Directory.GetFiles(_folder.Path));
    }

    /// <returns>True when the output was produced; false when this FFmpeg build lacks the encoder (allowed).</returns>
    private async Task<bool> AssertConvertedOrEncoderMissingAsync(ConversionTarget target, ConversionResult result)
    {
        if (result.Error == ConversionError.ToolMissing)
        {
            log.WriteLine($"{target.Id}: encoder missing in this FFmpeg build → {result.Message}");
            Assert.StartsWith("Your FFmpeg build lacks", result.Message, StringComparison.Ordinal);
            Assert.Empty(result.OutputPaths);
            return false;
        }

        Assert.True(result.Success, $"{target.Id} failed: {result.Error} {result.Message}");
        var output = result.OutputPaths.Single();
        Assert.Equal(target.OutputExtension, Path.GetExtension(output));
        Assert.True(new FileInfo(output).Length > 0, $"{target.Id}: empty output");
        Assert.True(await RealFfmpeg.DecodesCleanlyAsync(output), $"{target.Id}: output doesn't decode cleanly");
        log.WriteLine($"{target.Id}: OK → {Path.GetFileName(output)} ({new FileInfo(output).Length} bytes)");
        return true;
    }

    /// <summary>Logical screen width from a GIF89a header (bytes 6–7, little-endian).</summary>
    private static int GifWidth(string path)
    {
        var header = File.ReadAllBytes(path).AsSpan(0, 10);
        Assert.True(header[..6].SequenceEqual("GIF89a"u8), "Not a GIF89a file");
        return header[6] | (header[7] << 8);
    }

    private static HashSet<int> FfmpegPids()
    {
        var processes = Process.GetProcessesByName("ffmpeg");
        try
        {
            return processes.Select(p => p.Id).ToHashSet();
        }
        finally
        {
            foreach (var p in processes)
            {
                p.Dispose();
            }
        }
    }
}
